import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        s = next(iterator)
        n = len(s)

        if n % 2 != 0:
            results.append("NO")
            continue

        target = n // 2

        open_count = 0
        balance = 0
        possible = True

        for char in s:
            if char == '(':
                open_count += 1
                balance += 1
            elif char == ')':
                balance -= 1
            else:
                if open_count < target:
                    open_count += 1
                    balance += 1
                else:
                    balance -= 1

            if balance < 0:
                possible = False
                break

        if possible and balance == 0:
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
